// Author: MiYu. Exercise the original undead finale without a preexisting campaign cache.
#include "session.h"
#include "setup.h"
#include <iostream>

using namespace war3;
int wmain(int argc,wchar_t** argv){try{
    if(argc!=4)throw std::runtime_error("Usage: war3_undead_finale_tests <data-root> <Undead08.w3m> <new-absolute-user-dir>");fs::path user(argv[3]);if(!user.is_absolute() || !fs::create_directory(user) || !SetEnvironmentVariableW(L"MEGINE_WAR3_USER_DIR",user.c_str()))throw std::runtime_error("Cannot create isolated user directory");
    Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);ScriptSession s(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));s.campaignContext(false,1);s.attachWorld(std::move(world));s.audioSimulationClock();s.audioMuted(true);s.configure();PlayerSetup setup(info,s.config());s.applySetup(setup);s.startMain();auto& vm=s.runtime();auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto hero=vm.global("udg_Arthas"),lich=vm.global("udg_KelThuzad");require(hero.bits && lich.bits && s.units().contains(hero.bits) && s.units().contains(lich.bits),"Default campaign heroes missing");
    auto empty=vm.handle("unit",0);require(!call("UnitRemoveItemFromSlot",{empty,vm.integer(0)}).bits,"Null unit returned an item");auto unit=call("CreateUnit",{vm.handle("player",0x100003),vm.integer(int(ObjectData::code("hpea"))),vm.real(jass::Real::fromInteger(0)),vm.real(jass::Real::fromInteger(0)),vm.real(jass::Real::fromInteger(0))});call("RemoveUnit",{unit});require(!call("UnitRemoveItemFromSlot",{unit,vm.integer(0)}).bits,"Removed unit returned an item");auto item=call("UnitAddItemById",{hero,vm.integer(int(ObjectData::code("phea")))});require(item.bits && s.items().contains(item.bits),"Cannot add fixture item");auto& inventory=s.units().at(hero.bits)->inventory;unsigned slot=0;while(slot<inventory.size() && inventory[slot]!=item.bits)++slot;require(slot<inventory.size(),"Fixture item was not carried");require(!call("UnitRemoveItemFromSlot",{hero,vm.integer(-1)}).bits && !call("UnitRemoveItemFromSlot",{hero,vm.integer(6)}).bits,"Invalid inventory slot returned an item");require(call("UnitRemoveItemFromSlot",{hero,vm.integer(int(slot))}).bits==item.bits && s.items().contains(item.bits) && !s.items().at(item.bits)->holder,"Valid slot did not drop its item");require(!call("UnitRemoveItemFromSlot",{hero,vm.integer(int(slot))}).bits,"Empty slot returned an item");
    for(int i=0;i<720;++i)s.advance(.25);call("StartTimerBJ",{vm.global("udg_TimerSummoning"),vm.boolean(false),vm.real(jass::Real::fromInteger(5))});for(int i=0;i<1600 && s.exitRequest()==SessionExit::None;++i)s.advance(.25);auto owner=s.localPlayer().value_or(3);require(s.exitRequest()==SessionExit::Return && s.results()[owner] && *s.results()[owner]==0,"Undead finale victory not reached");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS undead finale opening, item removal and timer victory\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
